css:
.box {
  display: flex;
  flex-wrap: wrap;
  align-content: space-between; /* spread the lines top to bottom */
  gap: 8px;
  height: 220px;
  max-width: 300px;
  padding: 12px;
  border: 2px dashed #a1a1aa;
}

.tag {
  padding: 4px 10px;
  border: 1px solid #f97316;
  border-radius: 999px;
  background: #fed7aa;
}
